export function readCategory(r: BufferReader): Category {
  const id = r.u64();
  const parentId = r.u64();
  const name = r.fixedString(64);
  const slug = r.fixedString(128);
  const description = r.fixedString(1024);
  r.skip(2); // alignment gap before link_count
  const linkCount = r.u32();
  const childCount = r.u32();
  const sortOrder = r.u32();
  const linkCountSubtreeApproved = r.u32();
  const createdAt = r.timestamp();
  const updatedAt = r.timestamp();
  const linkCountSubtree = r.u64();
  const childCountSubtree = r.u32();
  const linkCountSubtreePending = r.u32();
  return {
    id,
    parentId,
    name,
    slug,
    description,
    linkCount,
    childCount,
    sortOrder,
    linkCountSubtreeApproved,
    createdAt,
    updatedAt,
    linkCountSubtree,
    childCountSubtree,
    linkCountSubtreePending,
  };
}

export function readLink(r: BufferReader): Link {
  const id = r.u64();
  const categoryId = r.u64();
  const url = r.fixedString(64);
  const title = r.fixedString(128);
  const description = r.fixedString(256);
  r.skip(2); // alignment gap before sort_order
  const sortOrder = r.u32();
  r.skip(4); // _pad0
  const createdAt = r.timestamp();
  const updatedAt = r.timestamp();
  const status = linkStatusFromByte(r.u8());
  r.skip(7); // _pad1
  const submitterId = r.u64();
  const editorNote = r.fixedString(1024);
  const tags = r.fixedString(256);
  const language = r.fixedString(8);
  const region = r.fixedString(8);
  const license = r.fixedString(64);
  r.skip(6); // _pad2
  return {
    id,
    categoryId,
    url,
    title,
    description,
    sortOrder,
    createdAt,
    updatedAt,
    status,
    submitterId,
    editorNote,
    tags,
    language,
    region,
    license,
  };
}
